  ('PM Vishwakarma Yojana 2026', 'Bank Passbook', 'verified', '2026-07-05T10:06:00Z', '2026-07-08T12:00:00Z'),
  ('Ayushman Bharat PMJAY 2026 Expansion', 'Aadhaar Card', 'verified', '2026-07-10T14:35:00Z', '2026-07-12T10:00:00Z'),
  ('Ayushman Bharat PMJAY 2026 Expansion', 'Ration Card', 'pending', '2026-07-10T14:36:00Z', '2026-07-10T14:36:00Z'),
  ('National Scholarship Portal 2026-27', 'Aadhaar Card', 'verified', '2026-07-18T09:05:00Z', '2026-07-19T09:00:00Z'),
  ('National Scholarship Portal 2026-27', 'Income Certificate', 'not_uploaded', '2026-07-18T09:06:00Z', '2026-07-18T09:06:00Z'),
  ('Stand-Up India 2026', 'Aadhaar Card', 'verified', '2026-07-08T12:05:00Z', '2026-07-09T10:00:00Z'),
  ('Stand-Up India 2026', 'Business Plan', 'verified', '2026-07-08T12:06:00Z', '2026-07-09T10:00:00Z'),
  ('Stand-Up India 2026', 'Project Report', 'pending', '2026-07-08T12:07:00Z', '2026-07-08T12:07:00Z')
) AS v(scheme_name, doc_name, doc_status, uploaded_at, updated_at)
